$root='api/LuxuryApp.Application/Modules/MantenimientoLuxuryApp/Piscinas'; $dto="$root/DTOs"; $src=Get-Content "$dto/PiscinaAddOrEditDTO.cs" -Raw; Set-Content "$dto/CreatePoolDTO.cs" ($src.Replace('PiscinaAddOrEditDTO','CreatePoolDTO')) -NoNewline; Set-Content "$dto/UpdatePoolDTO.cs" ($src.Replace('PiscinaAddOrEditDTO','UpdatePoolDTO')) -NoNewline; $read=Get-Content "$dto/PiscinaDTO.cs" -Raw; Set-Content "$dto/PoolDTO.cs" ($read.Replace('PiscinaDTO','PoolDTO')) -NoNewline; Remove-Item "$dto/PiscinaAddOrEditDTO.cs","$dto/PiscinaDTO.cs"; $map=@{'PiscinaAddOrEditDTO'='CreatePoolDTO';'PiscinaDTO'='PoolDTO'}; Get-ChildItem $root -Recurse -File -Filter *.cs | ForEach-Object {$c=Get-Content $_.FullName -Raw; foreach($k in $map.Keys){$c=$c.Replace($k,$map[$k])}; $c=$c.Replace('UpdateAsync(Guid id, CreatePoolDTO','UpdateAsync(Guid id, UpdatePoolDTO').Replace('MapPut("{id:guid}", async (Guid id, CreatePoolDTO','MapPut("{id:guid}", async (Guid id, UpdatePoolDTO'); Set-Content $_.FullName $c -NoNewline}
